declare(strict_types=1);
require_once __DIR__ . '/_tenant_users.php';[$identity,$tenant,$service,$administrativeContext]=requireTenantUserContext();$tenantId=$administrativeContext->getSelectedTenantId();$userId=filter_input(INPUT_GET,'user_id',FILTER_VALIDATE_INT)?:0;try{$user=$service->find($administrativeContext,$userId);}catch(DomainException $exception){http_response_code(404);echo platformEscape($exception->getMessage());exit;}$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{requirePlatformUserCsrf();$service->resetPassword($administrativeContext,$userId,(string)($_POST['senha']??''),(string)($_POST['confirmar_senha']??''));header('Location: /plataforma/empresa-usuarios.php?id='.$tenantId.'&password=1');exit;}catch(DomainException|InvalidArgumentException $exception){$error=$exception->getMessage();}}
renderPlatformStart($identity,'Redefinir senha','Empresas → '.($tenant['nome_fantasia']??'').' → Usuários → Senha');?>
<section class="panel"><p class="eyebrow">Tenant #<?= $tenantId ?></p><h1>Redefinir senha</h1><p class="muted">Usuário: <?= platformEscape($user['nome']) ?> · <?= platformEscape($user['email']) ?></p><?php if($error!==''):?><p class="message error" role="alert"><?= platformEscape($error) ?></p><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?= platformEscape($_SESSION['platform_user_csrf']) ?>"><div class="detail-grid"><label class="detail">Nova senha<input type="password" name="senha" minlength="8" required autocomplete="new-password"></label><label class="detail">Confirmar nova senha<input type="password" name="confirmar_senha" minlength="8" required autocomplete="new-password"></label></div><p class="muted">Mínimo de 8 caracteres, incluindo letra e número.</p><div class="form-actions"><button class="btn" type="submit">Redefinir senha</button><a class="btn secondary" href="/plataforma/empresa-usuarios.php?id=<?= $tenantId ?>">Cancelar</a></div></form></section><?php renderPlatformEnd(); ?>
